{"path": "/workspace/session_summarize_usage.py", "content": "def summarize_usage(events):
    """Summarize usage across events.

    Each event has a request_id and optional nonnegative integer input/output
    token counts (cumulative snapshots). For each request, keep the maximum
    input and output counts seen independently, then sum across requests.
    Missing counts are treated as 0. Negative counts raise ValueError.
    """
    if not isinstance(events, list):
        raise TypeError("events must be a list")

    max_input = {}
    max_output = {}

    for event in events:
        if not isinstance(event, dict):
            raise TypeError("each event must be a dict")
        request_id = event.get("request_id")
        if request_id is None:
            raise ValueError("each event must have a request_id")

        input_count = event.get("input")
        if input_count is not None:
            if not isinstance(input_count, int) or input_count < 0:
                raise ValueError("input count must be a nonnegative integer")
            if request_id not in max_input or input_count > max_input[request_id]:
                max_input[request_id] = input_count

        output_count = event.get("output")
        if output_count is not None:
            if not isinstance(output_count, int) or output_count < 0:
                raise ValueError("output count must be a nonnegative integer")
            if request_id not in max_output or output_count > max_output[request_id]:
                max_output[request_id] = output_count

    total_input = sum(max_input.values())
    total_output = sum(max_output.values())

    return {"input": total_input, "output": total_output}
"}
